+            "OMS" => ["cd", "name", "cdbase"].contains(&attribute.qname()),
+            "OMV" => attribute.qname() == "name",
+            "csymbol" => ["cd", "definitionURL"].contains(&attribute.qname()),
+            _ => false,
+        };
