+            return Err(invalid(format!(
+                "unsupported content attribute {} on {name}",
+                attribute.qname()
+            )));
+        }
+    }
+    if target == Target::MathMl && name == "cn" && node.attribute("type") == Some("rational") {
+        let children: Vec<_> = node
+            .children()
+            .filter(|child| child.is_element() || child.is_text())
+            .collect();
