+            sink.typed(&declaration, &math("FreeVariableDeclaration"))?;
+            sink.typed(&occurrence, &math("VariableOccurrence"))?;
+            sink.iri(&iri, &math("variableOccurrence"), &occurrence)?;
+            sink.iri(&occurrence, &math("declaredVariable"), &declaration)?;

