+        .into_iter()
+        .chain([RdfTerm::iri(math(class))])
+    {
+        mappings.extend(input.values(&class, SKOS_EXACT));
+        mappings.extend(input.values(&class, "http://www.w3.org/2004/02/skos/core#closeMatch"));
